<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
                return defaultValue;
            }
            current = current[key];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        // If the value is an array, return the first element (the actual value)
        // This is crucial for how updateProgressBar will use it.
        if (Array.isArray(current)) {
            return current.length > 0 ? current[0] : defaultValue;
        }
        return current;
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            // console.warn("Element with ID " + valueMainId + " not found.");
            return;
        }

        // rawValueFromCharacterData is ALREADY the direct value from SafeGetValue ( potentially array's first element)
        let workString = String(rawValueFromCharacterData); // Ensure it's a string

        // 1. Remove trailing " (description)" - this was from the 你's example's internal parsing
        // but if SafeGetValue always returns the clean value, this step might be redundant or for safety.
        // Given the requirement, we will make sure only to set the main value part using workString,
        // and the description part will be handled explicitly to be empty.
        const descMatch = workString.match(/\s*\((.*)\)$/);
        let cleanValue = workString;
        if (descMatch) {
            cleanValue = workString.substring(0, descMatch.index).trim();
        }

        // 2. Handle "oldValue -> newValue" format and take only newValue
        const parts = cleanValue.split('->');
        let finalDisplayValue = (parts.length > 1) ? parts[1].trim() : parts[0].trim();

        valueMainDisplay.innerText = finalDisplayValue;

        if (valueDescDisplay) { // ENSURE description span is ALWAYS empty
            valueDescDisplay.innerText = "";
        }

        const progressBar = barId ? document.getElementById(barId) : null;
        if (progressBar && typeof min === 'number' && typeof max === 'number') {
            let numericValue = parseFloat(finalDisplayValue);
            if (isNaN(numericValue)) { // If the final string is not purely numeric, parse original raw for number
                 const originalNumeric = parseFloat(String(rawValueFromCharacterData)); // Re-parse original value
                 numericValue = isNaN(originalNumeric) ? min : originalNumeric;
            }

            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = color || 'var(--accent-annanxiu)';
            if (percentage >= 100) {
                progressBar.classList.add('full');
            } else {
                progressBar.classList.remove('full');
            }
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            // --- 时间 & 地点 ---
            if (characterData.世界) {
                updateProgressBar(null, 'world-date', 'world-date-desc', SafeGetValue(characterData, '世界.日期', '--月--日'));
                let weekdayRaw = SafeGetValue(characterData, '世界.星期几', '--');
                let weekdayDisplay = String(weekdayRaw); // SafeGetValue should now directly return the '一' not ['一', 'desc']
                const weekdayMap = { "一": "星期一", "二": "星期二", "三": "星期三", "四": "星期四", "五": "星期五", "六": "星期六", "日": "星期日" };
                if (weekdayMap[weekdayDisplay]) {
                    weekdayDisplay = weekdayMap[weekdayDisplay];
                }
                updateProgressBar(null, 'world-day', 'world-day-desc', weekdayDisplay);
                updateProgressBar(null, 'world-time', 'world-time-desc', SafeGetValue(characterData, '世界.时间', '--:--'));
                updateProgressBar(null, 'world-location', 'world-location-desc', SafeGetValue(characterData, '世界.当前地点', '地球/未知'));
            } else {
                document.getElementById('world-date').innerText = '--月--日';
                document.getElementById('world-day').innerText = '--';
                document.getElementById('world-time').innerText = '--:--';
                document.getElementById('world-location').innerText = '地球/未知';
            }

            // --- 你 ---
            if (characterData.你) {
                updateProgressBar('你-life-energy-bar', '你-life-energy', '你-life-energy-desc', SafeGetValue(characterData, '你.生命能量', 0), 0, 100, 'var(--accent-你)');
            } else {
                updateProgressBar('你-life-energy-bar', '你-life-energy', '你-life-energy-desc', 0, 0, 100, 'var(--accent-你)');
            }

            // --- 安南秀 ---
            if (characterData.安南秀) {
                updateProgressBar('annanxiu-spirit-purity-bar', 'annanxiu-spirit-purity', 'annanxiu-spirit-purity-desc', SafeGetValue(characterData, '安南秀.精神纯度', 0), 0, 99, 'var(--accent-annanxiu)');
                updateProgressBar(null, 'annanxiu-affection', 'annanxiu-affection-desc', SafeGetValue(characterData, '安南秀.好感度', 0));
                updateProgressBar(null, 'annanxiu-posture', 'annanxiu-posture-desc', SafeGetValue(characterData, '安南秀.当前姿态', '未知'));
                updateProgressBar(null, 'annanxiu-action', 'annanxiu-action-desc', SafeGetValue(characterData, '安南秀.当前动作', '未知'));
                updateProgressBar(null, 'annanxiu-thought', 'annanxiu-thought-desc', SafeGetValue(characterData, '安南秀.当前想法', '未知'));
            } else {
                updateProgressBar('annanxiu-spirit-purity-bar', 'annanxiu-spirit-purity', 'annanxiu-spirit-purity-desc', 0, 0, 99, 'var(--accent-annanxiu)');
                updateProgressBar(null, 'annanxiu-affection', 'annanxiu-affection-desc', 0);
                updateProgressBar(null, 'annanxiu-posture', 'annanxiu-posture-desc', '未知');
                updateProgressBar(null, 'annanxiu-action', 'annanxiu-action-desc', '未知');
                updateProgressBar(null, 'annanxiu-thought', 'annanxiu-thought-desc', '未知');
            }

            const sectionHeaders = document.querySelectorAll('.status-card .card-body .section .section-header');
            if (sectionHeaders.length > 0) { // Expand first two sections (你 and An Nanxiu)
                 for(let i=0; i < Math.min(2, sectionHeaders.length); i++){
                    const content = sectionHeaders[i].nextElementSibling;
                    if (content && !content.classList.contains('expanded')) {
                        toggleSection(sectionHeaders[i]);
                    }
                 }
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
             console.error("Status bar error:", error);
        }
    }

    function toggleSection(element_or_event) {
        const element = element_or_event.target ? element_or_event.target.closest('.section-header') : element_or_event;
        if (!element) return;
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
